function createBaseCInventoryClientNewItemsNotification(): CInventoryClientNewItemsNotification {
  return { appid: 0, inventoryResponse: undefined };
}

export const CInventoryClientNewItemsNotification: MessageFns<CInventoryClientNewItemsNotification> = {
  encode(message: CInventoryClientNewItemsNotification, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.appid !== undefined && message.appid !== 0) {
      writer.uint32(8).uint32(message.appid);
    }
    if (message.inventoryResponse !== undefined) {
      CInventoryResponse.encode(message.inventoryResponse, writer.uint32(18).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): CInventoryClientNewItemsNotification {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseCInventoryClientNewItemsNotification();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.appid = reader.uint32();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.inventoryResponse = CInventoryResponse.decode(reader, reader.uint32());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },
};

